userscript.function:

	window.Sepoa = $sObject.Sepoa

    headerObj = $sObject.headerObj = new SepoaHeaderToolbarObject({
        parent:headerToolbar,
        height:50,
        logo:{
            align:"center",
            file:window.CONTEXT_NAME+"/theme/"+Sepoa.common.THEME+"/imgs/logo.png"
        },
        items:[
            {type: "text", id: "id", text:Sepoa.info.ID+" ("+Sepoa.info.NAME_LOC+")"},
            {type: "img", id: "logout", cursor:"pointer", img: window.CONTEXT_NAME+"/theme/"+Sepoa.common.THEME+"/imgs/icon/logout.png"}
        ]
    });
    headerObj.attachEvent("onClick", onHeaderClick)

    containerObj = $sObject.containerObj = new SepoaMainContainerObject({
        type:(dhx4.isIPad || dhx4.isIPhone)?'':Sepoa.config.get('sepoa.frame.type'),
        parent:mainContainer,
        tabbar:{
            mode:"bottom",
            align:"left",
            close_button:true,
            maxTabCount:Sepoa.config.get('sepoa.frame.maxcount'),
            tabs:[
                {
                    id:"SUMMARY",
                    text:Sepoa.cache.text.get("SUMMARY.TITLE"),
                    active:true,
                    close:false,
                    url:window.CONTEXT_NAME+"/Summary/SummaryLayout.sux"
                }
            ]
        },
        layout:{
            pattern:"1C",
            skin:"material",
            contents:true,
            cells:[
                {
                    header:false,
                    text:" ",
                    id:"a",
                    url:window.CONTEXT_NAME+"/Summary/SummaryLayout.sux"
                }
            ]
        }
    });

    SUX.callEvent('onWindowResize', []);


if(id == "logout"){
    Confirm("<span style='font-size: 1.2em;display: inline-block;text-align: left;'>"+Sepoa.cache.text.get('MAIN.ID')+Sepoa.info.ID+"\\n"
    +Sepoa.cache.text.get('MAIN.USER')+Sepoa.info.NAME_LOC+"</span>", function(flag){
        if(flag){
            location.href = window.CONTEXT_NAME+"/common/logout_process.jsp";
        }else{
            linkTo('AD_050','/Admin/UpdateUserInfo/AdminUpdateUserInfoLayout.sux');
        }
    },undefined,Sepoa.cache.text.get('MAIN.LOG_OUT'),Sepoa.cache.text.get('MAIN.CHANGE_USER_INFO'));
}else if(id == "logo"){
    openContainerUrl("SUMMARY", "/Summary/SummaryLayout.sux");
}


doServiceAjax('sepoa.svc.admin.AD_201','CONNECTION','getPopupNotice', {}, function( so ){
    if(so.status == 1){
        var l = so.message.split(',');
        var c = getCookie("sepoa.notice.ignore");
        if(c){
            c = c.split(',');
            for(var i in c){
                if(l.indexOf(c[i])+1){
                    l.splice(l.indexOf(c[i]), 1);
                }
            }
        }
        if(l.length > 0){
            PopupOpenPost(window.CONTEXT_NAME+'/Admin/NoticeView/AdminNoticeViewCarousel.sux', {NOTICELIST:l.join(',')}, '' , 1300, '', Sepoa.cache.text.get('MAIN.NOTICE'),'common');
        }
    }
});


            menuObj.render=function(){
                menuObj.tree = getMenuData(Sepoa.info.MENU_PROFILE_CODE);

                menuContainer.innerHTML = "";
                menuContainer.classList.add("topMenuArea")

                var ul = menuContainer.appendChild(document.createElement('ul'));

                for(var i in menuObj.tree){
                    var item = menuObj.tree[i];

                    var li = ul.appendChild(document.createElement('li'));
                    li.id = "sepoa_menu_group_"+item.ID
                    li.classList.add("sepoa_menu_group_li")
li.innerHTML = '<div><div class="sepoa_menu_group_icon" style="background-image:url('+window.CONTEXT_NAME+'/theme/<%=theme%>/leftmenu/icon/'+item.ICON_TYPE+');"></div><div class="sepoa_menu_group_name">'+item.MENU_NAME+'</div></div>';
                    li.data = item;
                    li.onmouseover = function(e){
                        $(ul).find(".sepoa_menu_group_li").removeClass("sepoa_menu_group_li_hover");

                        this.classList.add("sepoa_menu_group_li_hover")
                        menuObj.showDetail(e, this.data);
                    }
                    li.onmouseout = function(e){
                        menuObj.closeDetail(e);
                    }
                }
            };

            menuObj.closeDetail=function(e){
                if(e && e.toElement != menuContainer){
                    var tP = $(e.toElement).parents();
                    for(var i=0;i<tP.length; i++){
                        if(tP[i] == menuContainer){
                            return;
                        }
                    }
                }
                $(menuContainer).find(".sepoa_menu_group_li").removeClass("sepoa_menu_group_li_hover");
                menuObj.detailMenuBox.classList.remove("sepoa_menu_detail_show")
            }

            menuObj.showDetail=function(e, data){
                var detailMenuBox = menuObj.detailMenuBox;
                if(!detailMenuBox){
                    detailMenuBox = menuObj.detailMenuBox = document.createElement('div');
                    detailMenuBox.id = "sepoa_menu_detail_box";
                    detailMenuBox.className = "sepoa_menu_detail_box";
                    menuContainer.appendChild(detailMenuBox);
                }else if(detailMenuBox.data.MENU_ID == data.MENU_ID){
                    detailMenuBox.classList.add("sepoa_menu_detail_show");
                    return;
                }

                detailMenuBox.classList.add("sepoa_menu_detail_show");

                detailMenuBox.innerHTML = "";
                detailMenuBox.data = data;

                detailMenuBox.style.top = dhx.absTop(e.srcElement) - 2 + "px";
                detailMenuBox.style.left = dhx.absLeft(e.srcElement) + e.srcElement.offsetWidth + "px";

                var ul = document.createElement('ul');
                detailMenuBox.appendChild(ul);
                ul.className="sepoa_menu_detail_ul";

                for(var i in data.childs){
                    var item = data.childs[i];
                    var li = document.createElement('li');
                    ul.appendChild(li);
                    li.innerHTML = '<span>'+item.MENU_NAME+'</span>'
                    li.style.display=(item.HIDDEN_FLAG == 'Y')?"none":""
                    li.data = item;
                    li.onclick=function(e){
                        menuObj.closeDetail(e);
                        var _id = this.data.SCREEN_ID
                        var _url = this.data.URL
                        openContainerUrl(_id, _url, null);
                    }
                }

                detailMenuBox.onmouseout=function(e, data){
                    menuObj.closeDetail(e);
                }
            }
            menuObj.render();
